from collections import deque

def transform(lines):
 g=[list(map(int,s.split())) if ' ' in s else [int(x) for x in s] for s in lines]
 R,C=len(g),len(g[0]); dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 ext=set(); q=deque()
 for r in range(R):
  for c in range(C):
   if g[r][c]==0 and (r==0 or r==R-1 or c==0 or c==C-1): ext.add((r,c));q.append((r,c))
 while q:
  r,c=q.popleft()
  for dr,dc in dirs:
   p=(r+dr,c+dc)
   if 0<=p[0]<R and 0<=p[1]<C and g[p[0]][p[1]]==0 and p not in ext: ext.add(p);q.append(p)
 interior={(r,c) for r in range(R) for c in range(C) if g[r][c]==0 and (r,c) not in ext}
 # ones adjacent to any enclosed zero
 eligible=set()
 for r,c in interior:
  for dr,dc in dirs:
   p=(r+dr,c+dc)
   if 0<=p[0]<R and 0<=p[1]<C and g[p[0]][p[1]]==1: eligible.add(p)
 out=[row[:] for row in g]
 for r,c in interior:
  if any((r+dr,c+dc) in eligible for dr,dc in dirs): out[r][c]=3
 for r,c in ext:
  if any((r+dr,c+dc) in eligible for dr,dc in dirs): out[r][c]=2
 return [''.join(map(str,row)) for row in out]
