R=C=30;g=[[0]*C for _ in range(R)]
def h(r,a,b):
 for c in range(a,b+1):g[r][c]=1
def p(r,*cs):
 for c in cs:g[r][c]=1
h(1,25,29);p(2,25,29);p(3,25,29);p(4,24,25,29);p(5,24,29);h(6,24,29)
h(4,5,9);p(5,5);h(5,9,11);p(6,5,11);p(7,5,11);h(8,5,8);p(8,11);p(9,8,11);h(10,8,11)
h(4,18,20);p(5,18,20);p(6,18,20);h(7,18,20)
h(11,21,26)
for r in range(12,16):p(r,21,26)
h(16,8,16);h(16,21,24);p(16,26);p(17,8,16);p(18,8);p(19,8,16);p(20,8);h(21,8,11);p(21,16);p(22,11,16);p(23,11,16);h(24,11,16)
h(22,22,26);p(23,22,26);p(24,22,23,26);p(25,23,26);h(26,23,26)
D4=[(1,0),(-1,0),(0,1),(0,-1)];D8=[(a,b) for a in (-1,0,1) for b in (-1,0,1) if (a,b)!=(0,0)]
# enclosed zero cells by flood from edges
outside=set();q=deque()
for r in range(R):
 for c in range(C):
  if g[r][c]==0 and (r in (0,29) or c in (0,29)):outside.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in D4:
  z=r+dr,c+dc
  if 0<=z[0]<R and 0<=z[1]<C and g[z[0]][z[1]]==0 and z not in outside:outside.add(z);q.append(z)
inside={(r,c) for r in range(R) for c in range(C) if g[r][c]==0 and (r,c) not in outside}
# outer boundary (any zeros D8 adjacent to all shape) and inner 3 region full holes with boundary ring plus likely skip deeply isolated? full enclosed zero fill is candidate.
seen=set(); loopcells=set()
for r in range(R):
 for c in range(C):
  if g[r][c]!=1 or (r,c) in seen:continue
  q=[(r,c)];seen.add((r,c));co=[]
  while q:
   x,y=q.pop();co.append((x,y))
   for dr,dc in D4:
    z=x+dr,y+dc
    if 0<=z[0]<R and 0<=z[1]<C and g[z[0]][z[1]]==1 and z not in seen:seen.add(z);q.append(z)
  S=set(co);E=sum((x+dr,y+dc) in S for x,y in co for dr,dc in D4)//2
  if E-len(co)+1>0:loopcells|=S
out=[r[:] for r in g]
# recolor *all zero pixels inside closed outline* 3, preserving any enclosed-zero components not bounded by loop maybe inside set includes those
for r,c in inside:out[r][c]=3
# for external 2 paint zero pixels Moore-neighbor adjacent to closed loop
for r in range(R):
 for c in range(C):
  if g[r][c]==0 and (r,c) not in inside and any((r+dr,c+dc) in loopcells for dr,dc in D8 if 0<=r+dr<R and 0<=c+dc<C):out[r][c]=2
print('inside',len(inside),'loops',len(loopcells))
print(json.dumps(out,separators=(',',':')))

